import React, { useState, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';
import { FiChevronLeft, FiChevronRight } from 'react-icons/fi';
import { banners } from '../services/api';

const DEFAULT_BANNERS = [
  {
    _id: 'default-1',
    title: 'Summer Sale',
    imageUrl: 'https://images.unsplash.com/photo-1577803645773-f96470579636?w=1200&h=400&fit=crop',
    linkUrl: '/sale/summer',
  },
  {
    _id: 'default-2',
    title: 'New Arrivals',
    imageUrl: 'https://images.unsplash.com/photo-1511499767150-a48a237f0083?w=1200&h=400&fit=crop',
    linkUrl: '/brands/ray-ban',
  },
  {
    _id: 'default-3',
    title: 'Blue Cut Lenses',
    imageUrl: 'https://images.unsplash.com/photo-1574258495973-f010dfbb5371?w=1200&h=400&fit=crop',
    linkUrl: '/category/blue-cut',
  },
  {
    _id: 'default-4',
    title: 'Virtual Try-On',
    imageUrl: 'https://images.unsplash.com/photo-1508296695146-257a814070b4?w=1200&h=400&fit=crop',
    linkUrl: '/virtual-try-on',
  },
];

const styles = {
  container: {
    position: 'relative',
    width: '100%',
    overflow: 'hidden',
    background: '#f1f3f6',
  },
  track: {
    display: 'flex',
    transition: 'transform 0.5s ease-in-out',
  },
  slide: {
    minWidth: '100%',
    position: 'relative',
    cursor: 'pointer',
    overflow: 'hidden',
  },
  image: {
    width: '100%',
    height: '400px',
    objectFit: 'cover',
    display: 'block',
  },
  arrow: {
    position: 'absolute',
    top: '50%',
    transform: 'translateY(-50%)',
    background: 'rgba(255,255,255,0.9)',
    border: 'none',
    borderRadius: '50%',
    width: '44px',
    height: '44px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    cursor: 'pointer',
    zIndex: 10,
    fontSize: '20px',
    color: '#333',
    boxShadow: '0 2px 8px rgba(0,0,0,0.15)',
    transition: 'all 0.2s',
  },
  dots: {
    position: 'absolute',
    bottom: '20px',
    left: '50%',
    transform: 'translateX(-50%)',
    display: 'flex',
    gap: '8px',
    zIndex: 10,
  },
  dot: {
    width: '10px',
    height: '10px',
    borderRadius: '50%',
    border: 'none',
    cursor: 'pointer',
    transition: 'all 0.3s',
  },
};

export default function HeroCarousel() {
  const [current, setCurrent] = useState(0);
  const [paused, setPaused] = useState(false);
  const [bannerList, setBannerList] = useState(DEFAULT_BANNERS);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchBanners = async () => {
      try {
        const response = await banners.getActive();
        if (response.data.success && response.data.banners.length > 0) {
          setBannerList(response.data.banners);
        }
      } catch (error) {
        console.error('Error fetching banners:', error);
      } finally {
        setLoading(false);
      }
    };
    fetchBanners();
  }, []);

  const next = useCallback(() => {
    setCurrent((prev) => (prev + 1) % bannerList.length);
  }, [bannerList.length]);

  const prev = useCallback(() => {
    setCurrent((prev) => (prev - 1 + bannerList.length) % bannerList.length);
  }, [bannerList.length]);

  useEffect(() => {
    if (paused || bannerList.length === 0) return;
    const timer = setInterval(next, 4000);
    return () => clearInterval(timer);
  }, [next, paused, bannerList.length]);

  if (loading || bannerList.length === 0) {
    return (
      <div style={{ ...styles.container, height: '400px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div className="spinner" />
      </div>
    );
  }

  return (
    <div
      style={styles.container}
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
    >
      <div
        style={{
          ...styles.track,
          transform: `translateX(-${current * 100}%)`,
        }}
      >
        {bannerList.map((banner) => (
          <Link
            to={banner.linkUrl}
            key={banner._id}
            style={styles.slide}
          >
            <img
              src={banner.imageUrl}
              alt={banner.title}
              style={styles.image}
              className="hero-slide-image"
            />
          </Link>
        ))}
      </div>

      {bannerList.length > 1 && (
        <>
          <button
            style={{ ...styles.arrow, left: '16px' }}
            onClick={(e) => { e.preventDefault(); prev(); }}
            aria-label="Previous"
          >
            <FiChevronLeft />
          </button>
          <button
            style={{ ...styles.arrow, right: '16px' }}
            onClick={(e) => { e.preventDefault(); next(); }}
            aria-label="Next"
          >
            <FiChevronRight />
          </button>

          <div style={styles.dots}>
            {bannerList.map((_, i) => (
              <button
                key={i}
                style={{
                  ...styles.dot,
                  background: i === current ? '#fff' : 'rgba(255,255,255,0.5)',
                  transform: i === current ? 'scale(1.2)' : 'scale(1)',
                }}
                onClick={() => setCurrent(i)}
                aria-label={`Slide ${i + 1}`}
              />
            ))}
          </div>
        </>
      )}

      <style>{`
        @media (max-width: 768px) {
          .hero-slide-image { 
            height: 200px !important; 
          }
        }
        @media (max-width: 480px) {
          .hero-slide-image { 
            height: 150px !important; 
          }
        }
      `}</style>
    </div>
  );
}
